def view_entries(args):
    expenses = load_expenses()
    if not expenses:
        print("No expenses recorded.")
        return

    filtered = []
    start_date = datetime.strptime(args.from_date, "%Y-%m-%d") if args.from_date else None
    end_date = datetime.strptime(args.to, "%Y-%m-%d") if args.to else None

    for exp in expenses:
        exp_date = datetime.strptime(exp["date"], "%Y-%m-%d")
        if args.by == "date":
            if start_date and exp_date < start_date:
                continue
            if end_date and exp_date > end_date:
                continue
            filtered.append(exp)
        else:  # category
            if exp["category"].lower() != args.by.lower():
                continue
            filtered.append(exp)

    if not filtered:
        print("No matching entries.")
        return

