"""
household-tracker: Minimal CLI tool for tracking household expenses.
Stores data in expenses.json. No dependencies beyond standard library.
"""

import json
import argparse
import sys
from datetime import datetime
from pathlib import Path

DATA_FILE = "expenses.json"

def load_expenses():
    """Load expenses from JSON file, initialize empty list if missing."""
    try:
        with open(DATA_FILE, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []

def save_expenses(expenses):
    """Save expenses to JSON file atomically."""
    temp_file = Path(DATA_FILE).with_suffix(".tmp")
    try:
        with open(temp_file, 'w') as f:
            json.dump(expenses, f, indent=2)
        Path(temp_file).replace(DATA_FILE)
    except Exception as e:
        print(f"Error saving data: {e}", file=sys.stderr)
        sys.exit(1)

def validate_entry(entry):
    """Validate required fields and types."""
    required = ["date", "category", "description", "amount", "type"]
    for field in required:
        if field not in entry:
            raise ValueError(f"Missing required field: {field}")
    if not isinstance(entry["amount"], (int, float)) or entry["amount"] <= 0:
        raise ValueError("Amount must be a positive number")
    try:
        datetime.fromisoformat(entry["date"])
    except ValueError:
        raise ValueError("Date must be in ISO 8601 format (YYYY-MM-DD)")
    if entry["type"] not in ["expense", "income"]:
        raise ValueError("Type must be 'expense' or 'income'")

def next_id(expenses):
    """Return next available ID."""
    return max([e["id"] for e in expenses

